function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{toast('이 브라우저에서는 저장 공간을 사용할 수 없습니다.');}applyAppearance();}
function applyAppearance(){document.documentElement.dataset.theme=data.settings.theme;document.documentElement.dataset.readability=data.settings.large?'large':'normal';document.documentElement.style.setProperty('--base',data.settings.large?'17px':'15px');document.body.classList.toggle('compact',data.settings.compact);}
