function renderPage(){if(ui.section==='overview')return overviewPage();if(ui.section==='battle')return battlePage();if(ui.section==='tactics')return tacticsPage();if(ui.section==='records')return recordsPage();if(ui.section==='clan')return clanPage();return '';}
