function overviewPage(){const stats=allStats(),remaining=stats.reduce((s,m)=>s+m.remaining,0),carry=stats.filter(m=>m.carry>0).length,complete=stats.filter(m=>!m.remaining).length,total=stats.reduce((s,m)=>s+m.damage,0);
 let html=pageHeading('오늘의 전황',`CLAN BATTLE · DAY ${String(ui.day).padStart(2,'0')}`,'보스의 흐름과 남은 공격을 한눈에.')+pageTabs([['bosses','보스 현황'],['members','클랜원 현황',stats.length]])+`<div class="mobile-only mobile-day-switch">${dayButtons()}</div>`;
 if(ui.tabs.overview==='members')return html+memberDashboard();
 return html+`<div class="overview-main"><div class="stat-strip">${stat('남은 공격',`${remaining}<small>/ ${stats.length*data.settings.daily}타</small>`,'기본 공격 기준','bolt')}${stat('이월 보유',`${carry}<small>명</small>`,'격파 후 남은 이월','clock')}${stat('공격 완료',`${complete}<small>/ ${stats.length}명</small>`,`<em>${Math.round(complete/stats.length*100)}%</em> 진행`,'users')}${stat('누적 피해량',`${eok(total)}<small>억</small>`,'초과 피해를 제외한 합계','chart')}</div><section class="boss-section"><div class="section-head"><h2>보스 진행 현황</h2><div class="section-meta">${icon('info')}보스를 누르면 공격 기록으로 연결</div></div><div class="boss-grid">${data.bosses.map(bossCard).join('')}</div></section></div><div class="overview-bottom"><section class="panel"><div class="panel-head"><div><h2>최근 배틀로그</h2><p>가장 최근에 등록한 공격</p></div><button class="text-button" data-action="nav" data-value="battle">전체 보기 ${icon('arrow')}</button></div>${logTable([...data.logs].filter(l=>l.day<=ui.day).reverse().slice(0,6),true)}</section><section class="panel"><div class="panel-head"><div><h2>남은 공격</h2><p>${ui.day}일차 · 남은 타수 순</p></div><button class="text-button" data-action="overview-members">${icon('arrow')}<span class="sr-only">클랜원 현황 전체 보기</span></button></div><div class="waiting-list">${stats.filter(m=>m.remaining).sort((a,b)=>b.remaining-a.remaining||b.carry-a.carry).slice(0,5).map(m=>`<button class="waiting-row" data-action="profile" data-id="${m.member.id}">${avatar(m.member)}<span class="waiting-name">${X(m.member.name)}<small>${m.carry?`이월 ${m.carry}타 보유`:'기본 공격 대기'}</small></span><span class="remaining-dots">${Array.from({length:3},(_,i)=>`<i class="${i<m.remaining?'on':''}"></i>`).join('')}</span><span class="remaining-value numeric">${m.remaining}타</span></button>`).join('')}</div><div class="panel-note">이월 공격은 기본 타수와 별도로 표시합니다.</div></section></div>`;
}
function bossCard(b){const percent=b.hp/b.max*100,locked=isLocked(b);return `<button class="boss-card ${locked?'locked':''}" style="${bossStyle(b.id)}" data-action="boss-log" data-id="${b.id}" aria-label="${b.id}넴 ${X(b.name)}, 남은 HP ${nf(b.hp)}, ${locked?'회차 대기':'공격 기록'}"><div class="boss-top"><span class="boss-emblem">${icon(b.icon)}</span><span class="boss-index">BOSS ${String(b.id).padStart(2,'0')}</span></div><h3 class="boss-name">${X(b.name)}</h3><div class="boss-round"><span>${b.stage}단계</span><span>·</span><span>${b.lap}회차</span></div><div class="boss-hp numeric"><small>남은 HP</small>${nf(b.hp)}</div><div class="progress" role="progressbar" aria-label="${X(b.name)} 남은 HP 비율" aria-valuenow="${Math.round(percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent}%"></span></div><div class="boss-foot">${locked?`<span class="locked">${icon('lock')}회차 대기</span>`:`<span>${b.hp<400000000?'격파권 진입':'공격 가능'}</span>`}<strong class="numeric">${percent.toFixed(1)}%</strong></div></button>`;}
function memberDashboard(){let rows=allStats();rows.sort((a,b)=>{if(ui.memberSort==='name')return a.member.name.localeCompare(b.member.name,'ko')*ui.sortDir;return ((a[ui.memberSort]||0)-(b[ui.memberSort]||0))*ui.sortDir;});return `<div class="toolbar"><p class="member-summary">${ui.day}일차 남은 기본 공격과 이월을 함께 확인하세요.</p><div class="toolbar-right"><button class="button sm" data-action="export-csv">${icon('download')}표 내보내기</button></div></div><section class="panel"><div class="table-wrap"><table class="member-table"><thead><tr><th>${memberSort('name','클랜원')}</th>${Array.from({length:data.settings.days},(_,i)=>`<th class="center hide-mobile">${i+1}일차</th>`).join('')}<th class="right">${memberSort('remaining','남은 타수')}</th><th class="right">${memberSort('carry','이월')}</th><th class="right hide-mobile">${memberSort('dayDamage','오늘 피해량')}</th></tr></thead><tbody>${rows.map(m=>`<tr><td><div class="member-name">${avatar(m.member)}<button class="text-button member-link" data-action="profile" data-id="${m.member.id}">${X(m.member.name)}</button></div></td>${Array.from({length:data.settings.days},(_,i)=>{const used=dayLogs(m.member.id,i+1).filter(l=>l.type!=='carry'&&!l.usesCarry).length;return `<td class="center hide-mobile"><span class="daily-use" aria-label="${i+1}일차 ${used}타">${Array.from({length:data.settings.daily},(_,n)=>`<i class="${n<used?'used':''}"></i>`).join('')}</span></td>`;}).join('')}<td class="right"><span class="${m.remaining?'':'muted'} numeric">${m.remaining?`<strong>${m.remaining}</strong>타`:'완료'}</span></td><td class="right">${m.carry?`<span class="badge amber">${m.carry}타</span>`:'<span class="faint">—</span>'}</td><td class="right hide-mobile numeric">${nf(m.dayDamage)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function memberSort(key,label){return `<button class="sort-button ${ui.memberSort===key?'active':''}" data-action="member-sort" data-value="${key}">${label}${icon('sort')}</button>`;}
const logTypeLabel=t=>({normal:'일반',carry:'이월타',kill:'격파'}[t]||'일반');
function logTable(logs,mini=false){return `<div class="table-wrap"><table class="log-table"><thead><tr>${mini?'':'<th class="hide-mobile">진행</th>'}<th>보스</th><th>클랜원</th><th class="right">실제 피해량</th><th class="center">유형</th>${mini?'':'<th class="hide-mobile right">관리</th>'}</tr></thead><tbody>${logs.length?logs.map(l=>{const m=currentMember(l.memberId);return `<tr>${mini?'':`<td class="hide-mobile">${l.day}일차<small>${l.stage}단계 · ${l.lap}회차</small></td>`}<td><span class="boss-dot" style="${bossStyle(l.boss)}"><i></i>${l.boss}넴<span class="hide-mobile"> · ${X(bossBy(l.boss).name.slice(0,6))}</span></span>${mini?`<small>${l.day}일차 · ${l.lap}회차</small>`:''}</td><td class="name"><button class="text-button member-link" data-action="profile" data-id="${m.id}">${X(m.name)}</button></td><td class="numeric right">${mini?nf(l.actual):`<button class="damage-edit numeric" data-action="edit-log" data-id="${l.id}" aria-label="${X(m.name)}의 ${l.seq}번 공격 피해량 ${nf(l.actual)} 수정">${nf(l.actual)}</button>`}</td><td class="center"><span class="badge ${l.type==='carry'?'blue':l.type==='kill'?'green':''}">${logTypeLabel(l.type)}</span></td>${mini?'':`<td class="right hide-mobile"><button class="text-button" data-action="edit-log" data-id="${l.id}" aria-label="${X(m.name)}의 ${l.seq}번 공격 수정">${icon('edit')}</button></td>`}</tr>`;}).join(''):'<tr><td colspan="6">'+empty('공격 기록이 없습니다.','다른 일차나 보스를 선택하거나 새 기록을 추가해보세요.')+'</td></tr>'}</tbody></table></div>`;}
function filteredLogs(){return data.logs.filter(l=>l.day===ui.day&&(!ui.boss||l.boss===ui.boss)&&(ui.logType==='all'||l.type===ui.logType)&&(!ui.query||currentMember(l.memberId).name.includes(ui.query)||String(l.seq)===ui.query)).sort((a,b)=>b.seq-a.seq);}
function compactBosses(){return `<div class="compact-bosses">${data.bosses.map(b=>`<button class="compact-boss" style="${bossStyle(b.id)}" data-action="boss-log" data-id="${b.id}"><span class="boss-emblem">${icon(b.icon)}</span><div><small>${b.id}넴 <span>· ${b.lap}회차</span></small><strong class="numeric">${short(b.hp)}</strong></div></button>`).join('')}</div>`;}
function bossFilter(){return `<div class="filter-group boss-filter" role="group" aria-label="보스 필터">${[0,1,2,3,4,5].map(id=>`<button data-action="boss-filter" data-value="${id}" ${id?`style="${bossStyle(id)}"`:''} class="${ui.boss===id?'active':''}" aria-pressed="${ui.boss===id}">${id?id+'넴':'전체'}</button>`).join('')}</div>`;}
function battlePage(){const logs=filteredLogs(),pageSize=10,maxPage=Math.max(1,Math.ceil(logs.length/pageSize));ui.page=Math.min(ui.page,maxPage);return pageHeading('배틀로그','BATTLE LOG','공격 기록을 남기고, 다음 흐름을 이어가세요.')+`<div class="mobile-only mobile-day-switch">${dayButtons()}</div>`+compactBosses()+`<div class="toolbar"><div class="toolbar-left">${bossFilter()}</div><div class="toolbar-right"><div class="search-field">${icon('search')}<input id="log-query" aria-label="클랜원 또는 순번 검색" data-input="log-query" placeholder="클랜원 · 순번 검색" value="${X(ui.query)}"></div><select class="select-field" aria-label="공격 유형" data-input="log-type"><option value="all">전체 유형</option>${['normal','carry','kill'].map(v=>`<option value="${v}" ${ui.logType===v?'selected':''}>${logTypeLabel(v)}</option>`).join('')}</select><button class="button icon-only desktop-only" data-action="image-import" aria-label="이미지 보며 기록하기">${icon('image')}</button></div></div><section class="panel"><div class="panel-head"><h2>${ui.day}일차 공격 내역 <span class="count">${logs.length}</span></h2><button class="text-button" data-action="export-csv">${icon('download')}<span class="desktop-only">내보내기</span></button></div>${logTable(logs.slice((ui.page-1)*pageSize,ui.page*pageSize))}<div class="pagination"><span>${logs.length?`${(ui.page-1)*pageSize+1}–${Math.min(ui.page*pageSize,logs.length)} / ${logs.length}건`:'0건'}</span><div><button data-action="log-page" data-value="${ui.page-1}" ${ui.page===1?'disabled':''}>이전</button><span class="numeric">${ui.page} / ${maxPage}</span><button data-action="log-page" data-value="${ui.page+1}" ${ui.page===maxPage?'disabled':''}>다음</button></div></div></section><p class="helper">기록은 이 브라우저에서만 바뀝니다. 실제 클랜전 데이터와 연결되어 있지 않습니다.</p>`;}
function party(t){return `<div class="party">${t.party.map((name,i)=>{const index=CHARACTERS.indexOf(name),c=COLORS[(Math.max(index,0)+i)%COLORS.length];return `<div class="unit ${i===t.support?'support':''}"><div class="portrait" style="--unit-bg:${c[0]};--unit-ink:${c[1]}">${X(name.slice(0,1))}</div><strong>${X(name)}</strong><small class="${![5,6].includes(Number(t.stars[i]))?'danger':''}">★ ${X(t.stars[i]||5)}${i===t.support?' · 빌림':''}</small></div>`;}).join('')}</div>`;}
function tacticsPage(){return pageHeading('택틱 라이브러리','TACTICS & STRATEGY','조합을 고르고, 필요한 순간에 정확하게.',ui.tabs.tactics==='workspace'?'new-tactic':'')+pageTabs([['workspace','작업실'],['combos','추천 조합'],['tools','이월 도구']])+({combos:comboPage,workspace:workspacePage,tools:carryPage}[ui.tabs.tactics]||workspacePage)();}
function tacticTpClass(value){const s=String(value??'');return s.includes('+')?'danger':/[-−－﹣]/.test(s)?'tp-negative':'';}
function tacticMeta(t){return `<span class="${t.hands>0?'danger':''}">손컨 <strong class="${t.hands>0?'danger':''}">${t.hands}</strong></span><span class="${tacticTpClass(t.tp)}">TP <strong class="${tacticTpClass(t.tp)}">${X(t.tp)}</strong></span><span>성급 <strong>${t.stars.map(n=>`<span class="${![5,6].includes(Number(n))?'danger':''}">${X(n)}</span>`).join('')}</strong></span>`;}
function comboPage(){const tactics=data.tactics.filter(t=>!t.hidden&&(!ui.boss||t.boss===ui.boss)).sort((a,b)=>a.boss-b.boss||b.damage-a.damage);return `<div class="toolbar"><div class="toolbar-left">${bossFilter()}</div><div class="toolbar-right"><span class="badge">4단계</span><span class="section-meta">${tactics.length}개 조합</span><button class="text-button" data-action="auto-plan">${icon('spark')}3타 예시 구성</button></div></div><div class="info-line">${icon('info')}<span>초상화 대신 문자 아바타를 사용한 예시 조합입니다. 카드를 골라 3타를 구성하거나 상세 택틱을 열어보세요.</span></div><div class="tactic-grid">${tactics.map(t=>`<article class="tactic-card ${ui.picks.includes(t.id)?'selected':''}" style="${bossStyle(t.boss)}"><div class="tactic-head"><div class="tactic-boss"><strong>${t.boss}넴</strong><span>${X(bossBy(t.boss).name)}</span><span class="tactic-type">${t.category==='tabi'?'타비비토':'택틱'}</span></div><button class="pick-button" data-action="pick-tactic" data-id="${t.id}" aria-label="${t.boss}넴 ${X(t.title)} ${ui.picks.includes(t.id)?'선택 해제':'3타에 추가'}" aria-pressed="${ui.picks.includes(t.id)}">${icon(ui.picks.includes(t.id)?'check':'plus')}</button></div>${party(t)}<div class="tactic-metadata">${tacticMeta(t)}</div><div class="tactic-bottom"><div><div class="damage-label">기대 피해량</div><div class="damage-value numeric">${t.damage.toFixed(1)}<small>억</small></div></div><button class="button sm quiet" data-action="tactic-detail" data-id="${t.id}">택틱 보기 ${icon('arrow')}</button></div></article>`).join('')}</div>${planTray()}`;}
function planTray(){if(!ui.picks.length)return '';const chosen=ui.picks.map(id=>data.tactics.find(t=>t.id===id)).filter(Boolean),total=chosen.reduce((s,t)=>s+t.damage,0),seen=new Set();let overlap=false;for(const t of chosen)for(const [i,c]of t.party.entries()){if(i===t.support)continue;if(seen.has(c))overlap=true;seen.add(c);}return `<div class="plan-tray"><div class="plan-slots">${Array.from({length:3},(_,i)=>chosen[i]?`<div class="plan-slot">${chosen[i].boss}넴 · ${chosen[i].damage.toFixed(1)}억<button data-action="pick-tactic" data-id="${chosen[i].id}" aria-label="${i+1}번째 조합 선택 해제">×</button></div>`:`<div class="plan-slot empty">${i+1}번째 공격</div>`).join('')}</div><div class="plan-total">합계<strong class="numeric">${total.toFixed(1)}억</strong>${overlap?'<div class="plan-note">캐릭터 중복 · 서포트 구성을 확인하세요</div>':''}</div><button class="button sm" data-action="clear-plan">비우기</button></div>`;}
function libraryTactics(){return data.tactics.filter(t=>(ui.library==='hidden'?t.hidden:!t.hidden)&&(ui.library==='all'||ui.library==='hidden'||t.category===ui.library)&&(!ui.boss||t.boss===ui.boss)).sort((a,b)=>a.boss-b.boss||b.damage-a.damage);}
function workspacePage(){const list=libraryTactics();let selected=list.find(t=>t.id===ui.selectedTactic)||list[0];if(selected)ui.selectedTactic=selected.id;return `<div class="toolbar"><div class="toolbar-left"><div class="filter-group" aria-label="택틱 분류">${[['all','전체'],['main','택틱정리'],['tabi','타비비토'],['hidden','숨김']].map(([k,n])=>`<button data-action="library" data-value="${k}" class="${ui.library===k?'active':''}">${n}${k==='hidden'?` ${data.tactics.filter(t=>t.hidden).length}`:''}</button>`).join('')}</div></div><div class="toolbar-right">${bossFilter()}</div></div><div class="workspace-grid"><section class="panel tactic-library ${ui.libraryOpen?'expanded':''}"><div class="panel-head"><div><h2>등록된 택틱 <span class="count">${list.length}</span></h2><p class="mobile-only">${selected?X(selected.party.slice(0,3).join(' · ')):'택틱을 선택하세요'}</p></div><span class="desktop-only">${icon('tactic')}</span><button class="text-button mobile-only" data-action="toggle-library" aria-expanded="${ui.libraryOpen}">${ui.libraryOpen?'목록 닫기':'목록 열기'}</button></div><div class="library-scroll">${list.length?list.map((t,i)=>`${i===0||list[i-1].boss!==t.boss?`<div class="library-group-label">${t.boss}넴 · ${X(bossBy(t.boss).name)}</div>`:''}<button class="library-item ${selected?.id===t.id?'active':''}" data-action="select-tactic" data-id="${t.id}"><strong>${X(t.party.slice(0,3).join(' · '))}</strong><small>기대딜 ${t.damage.toFixed(1)}억 · <span class="${t.hands?'danger':''}">손컨 ${t.hands}</span> · ${t.category==='tabi'?'타비':'택틱'}</small></button>`).join(''):empty('등록된 택틱이 없습니다.','분류를 바꾸거나 새 택틱을 추가하세요.')}</div></section>${selected?workspaceEditor(selected):`<section class="panel">${empty('택틱을 선택하세요.','등록한 택틱은 추천 조합에도 반영됩니다.',`<button class="button primary" data-action="new-tactic">새 택틱</button>`)}</section>`}</div>`;}
function workspaceEditor(t){const b=bossBy(t.boss);return `<section class="panel"><div class="editor-section"><div class="editor-meta"><span class="badge" style="color:var(--b${t.boss})">${t.boss}넴 · ${X(b.name)}</span><span class="badge">${t.stage}단계</span>${t.hidden?'<span class="badge amber">숨긴 택틱</span>':''}</div><h2 class="editor-title">${X(t.title)}</h2><div class="tactic-metadata" style="border:0;padding:5px 0 13px">${tacticMeta(t)}<span>기대딜 <strong>${t.damage.toFixed(1)}억</strong></span></div>${party(t)}<div class="editor-controls"><div class="carry-inline"><label for="workspace-carry">이월 시간</label><input id="workspace-carry" aria-label="택틱 이월 받은 시간" value="${fmtTime(ui.carry)}" data-input="workspace-carry" inputmode="numeric"><button class="text-button" data-action="reset-carry">원본</button></div><div class="toolbar-left"><button class="button sm quiet" data-action="copy-tactic" data-id="${t.id}">${icon('copy')}복사</button><button class="button sm" data-action="edit-tactic" data-id="${t.id}">${icon('edit')}수정</button></div></div></div><div id="workspace-timeline">${timeline(t)}</div><div class="editor-section"><div class="toolbar"><div class="toolbar-left"><button class="text-button" data-action="hide-tactic" data-id="${t.id}">${icon(t.hidden?'eye':'eyeoff')}${t.hidden?'다시 공개':'숨기기'}</button><button class="text-button" data-action="duplicate-tactic" data-id="${t.id}">${icon('copy')}복제</button></div><button class="text-button danger" data-action="delete-tactic" data-id="${t.id}">${icon('trash')}삭제</button></div><p class="helper">${X(t.note)}${t.hidden?'<br>숨긴 택틱은 작업실에 남고 추천 조합에서는 제외됩니다.':''}</p></div></section>`;}
function timeToSec(v){const s=String(v).trim();if(/^\d{1,2}:\d{2}$/.test(s)){const [m,n]=s.split(':').map(Number);return n<60?m*60+n:NaN;}return /^\d+$/.test(s)?Number(s):NaN;}
function fmtTime(n){const sign=n<0?'-':'';n=Math.abs(Math.round(n));return `${sign}${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function adjustedText(text,seconds=ui.carry){const offset=seconds-90;return text.replace(/\b(\d{1,2}):(\d{2})\b/g,(full,m,s)=>{const n=Number(m)*60+Number(s);return n<=90?fmtTime(n+offset):full;});}
function timeline(t,seconds=ui.carry){return `<table class="timeline-table"><thead><tr><th>남은 시간</th><th>행동 · SET</th></tr></thead><tbody>${t.text.split('\n').filter(Boolean).map(line=>{const match=line.match(/^(\d{1,2}:\d{2})\s*(.*)$/),sec=match?timeToSec(match[1])+seconds-90:null;const action=X(match?match[2]:line).replace(/(ON|SET|한번만)/g,'<strong>$1</strong>');return `<tr class="${sec!==null&&sec<0?'after-end':''}"><td class="mono">${sec===null?'—':fmtTime(sec)}</td><td>${action}</td></tr>`;}).join('')}</tbody></table>`;}
function carryPage(){return `<div class="tool-grid"><section class="panel"><div class="panel-head"><div><h2>이월 시간 계산</h2><p>격파 후 받은 시간으로 택틱을 맞춰보세요.</p></div>${icon('clock')}</div><div class="panel-body"><div class="field"><label for="carry-remaining">격파 순간 남은 시간</label><input id="carry-remaining" value="0:36" data-input="carry-calculator" inputmode="numeric"><small>예: 0:36 또는 36</small></div><div class="field"><label for="carry-bonus">추가 시간</label><div class="input-unit"><input id="carry-bonus" type="number" min="0" max="90" value="20" data-input="carry-calculator"><span>초</span></div></div><div class="calculated"><small>받을 수 있는 이월 시간</small><strong class="mono" id="carry-result">0:56</strong></div><button class="button primary full" data-action="apply-calculated-carry">${icon('check')}작업실 택틱에 적용</button><p class="helper">남은 시간 + 추가 시간, 최대 1:30 기준으로 계산합니다.<br>게임에서 실제 받은 시간을 확인하고 적용하세요.</p></div></section><section class="panel"><div class="panel-head"><div><h2>외부 택틱 시간 맞추기</h2><p>원문은 유지하고 시간만 바꿉니다.</p></div>${icon('file')}</div><div class="panel-body"><div class="field-row"><div class="field"><label for="external-carry">이월 받은 시간</label><input id="external-carry" value="${fmtTime(ui.carry)}" data-input="external-tactic" inputmode="numeric"></div><div class="field"><label>원본 전투 시간</label><input value="1:30" readonly aria-label="원본 전투 시간 1분 30초"></div></div><div class="field"><label for="external-text">복사한 택틱</label><textarea id="external-text" data-input="external-tactic" spellcheck="false">1:30 AUTO ON, 콧코로 SET\n1:12 레이 후 유이 ON\n0:38 전원 SET\n0:06 AUTO OFF</textarea></div><div class="section-head"><span class="field-label">시간을 맞춘 결과</span><button class="text-button" data-action="copy-external">${icon('copy')}복사</button></div><pre id="external-output" class="code-output"></pre><p class="helper">음수 시간은 해당 이월 전투가 종료된 뒤의 시점입니다. 행동이나 캐릭터 순서는 변환하지 않습니다.</p></div></section></div>`;}
function updateCarryTool(){const remaining=timeToSec(document.getElementById('carry-remaining')?.value||''),bonus=Number(document.getElementById('carry-bonus')?.value||0),result=document.getElementById('carry-result');if(result)result.textContent=Number.isFinite(remaining)&&remaining<=90&&remaining>=0?fmtTime(Math.min(90,remaining+Math.max(0,bonus))):'시간 확인';const field=document.getElementById('external-carry'),output=document.getElementById('external-output');if(field&&output){const s=timeToSec(field.value);output.textContent=Number.isFinite(s)&&s>0&&s<=90?adjustedText(document.getElementById('external-text').value,s):'0:01부터 1:30 사이의 시간을 입력하세요.';}}
function recordsPage(){return pageHeading('클랜의 기록','RECORDS & INSIGHTS','이번 달의 성과부터 함께 쌓은 기록까지.','')+pageTabs([['ranking','월간 순위'],['profile','개인 이력'],['archive','지난 클랜전'],['hall','명예의 전당']])+({ranking:rankingPage,profile:profilePage,archive:archivePage,hall:hallPage}[ui.tabs.records]||rankingPage)();}
function rankHead(key,label){return `<button class="sort-button ${ui.rankSort===key?'active':''}" data-action="rank-sort" data-value="${key}">${label}${icon('sort')}</button>`;}
function rankingPage(){const rows=allStats().sort((a,b)=>b[ui.rankSort]-a[ui.rankSort]);return `<div class="toolbar"><div class="toolbar-left"><span class="member-summary">${ui.day}일차까지 누적 · 항목을 눌러 정렬</span></div><div class="toolbar-right"><button class="button sm" data-action="print">${icon('print')}PDF · 인쇄</button></div></div><section class="panel"><div class="table-wrap"><table class="ranking-table"><thead><tr><th class="center">순위</th><th>클랜원</th><th class="right">${rankHead('contribution','기여도')}</th><th class="right hide-mobile">${rankHead('damage','실제 피해량')}</th><th class="right hide-mobile">${rankHead('average','평균 기여도')}</th><th class="right">${rankHead('shots','공격 수')}</th></tr></thead><tbody>${rows.map((m,i)=>`<tr><td class="center"><span class="rank-mark ${i===0?'first':i<3?'second':''}">${i+1}</span></td><td><div class="member-name">${avatar(m.member)}<button class="text-button member-link" data-action="profile" data-id="${m.member.id}">${X(m.member.name)}</button></div></td><td class="right numeric"><strong>${short(m.contribution)}</strong></td><td class="right numeric hide-mobile">${short(m.damage)}</td><td class="right numeric hide-mobile">${short(m.average)}</td><td class="right numeric">${m.shots}<span class="faint">타</span></td></tr>`).join('')}</tbody></table></div></section><p class="helper">이 시제품의 기여도는 예시 배율을 적용한 수치입니다. 실제 기록이나 순위가 아닙니다.</p>`;}
function profilePage(){const m=currentMember(ui.profile),stats=memberStats(m),daily=Array.from({length:data.settings.days},(_,i)=>({day:i+1,damage:dayLogs(m.id,i+1).reduce((s,l)=>s+l.actual,0)})),max=Math.max(...daily.map(d=>d.damage),1),bossTotal=stats.damage||1;return `<div class="profile-header"><div class="profile-identity">${avatar(m)}<div><h2>${X(m.name)}</h2><p>${X(m.uid)} · ${ui.day}일차까지</p></div></div><select class="select-field" aria-label="개인 이력 클랜원" data-input="profile-member">${data.members.map(p=>`<option value="${p.id}" ${p.id===m.id?'selected':''}>${X(p.name)}</option>`).join('')}</select></div><div class="stat-strip">${stat('누적 피해량',`${eok(stats.damage)}<small>억</small>`,'실제 피해량 합계')}${stat('기여도',`${eok(stats.contribution)}<small>억</small>`,'예시 배율 적용')}${stat('공격 횟수',`${stats.shots}<small>타</small>`,'기본 공격 + 이월')}${stat('공격당 평균',`${eok(stats.average)}<small>억</small>`,'평균 기여도')}</div><div class="profile-grid"><section class="panel"><div class="panel-head"><div><h2>일차별 피해량</h2><p>각 일차 실제 피해량의 합계</p></div></div><div class="daily-chart" role="img" aria-label="${X(m.name)} 일차별 피해량: ${daily.map(d=>d.day+'일차 '+nf(d.damage)).join(', ')}">${daily.map(d=>`<div class="daily-bar"><span class="bar-value numeric">${d.damage?eok(d.damage)+'억':'—'}</span><div class="bar-track"><span style="height:${d.damage/max*100}%;opacity:${d.day===ui.day?1:.65}"></span></div><span class="bar-label">${d.day}일차</span></div>`).join('')}</div><div class="panel-body" style="padding-top:20px"><button class="text-button" data-action="print">${icon('print')}개인 이력 PDF · 인쇄</button></div></section><section class="panel"><div class="panel-head"><div><h2>보스별 공격 비중</h2><p>누적 실제 피해량 기준</p></div></div><div class="share-list">${data.bosses.map(b=>{const amount=stats.logs.filter(l=>l.boss===b.id).reduce((s,l)=>s+l.actual,0);return `<div class="share-row" style="${bossStyle(b.id)}"><div><span>${b.id}넴 · ${X(b.name)}</span><strong class="numeric">${(amount/bossTotal*100).toFixed(0)}%</strong></div><div class="progress"><span style="width:${amount/bossTotal*100}%"></span></div></div>`;}).join('')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>최근 공격</h2><button class="text-button" data-action="member-log" data-id="${m.id}">로그에서 보기 ${icon('arrow')}</button></div>${logTable([...stats.logs].reverse().slice(0,5),true)}</section>`;}
const ARCHIVES=[{month:'2026-09',rank:128,damage:72900000000,lap:41,attacks:443},{month:'2026-08',rank:136,damage:68100000000,lap:38,attacks:438},{month:'2026-07',rank:154,damage:62400000000,lap:35,attacks:431}];
function archivePage(){return `<div class="info-line">${icon('info')}<span>아래는 화면 구성을 확인하기 위한 과거 기록 예시입니다. 현재 전황과 분리해 열립니다.</span></div><div class="archive-grid">${ARCHIVES.map(a=>`<article class="panel archive-card"><div class="section-head"><span class="archive-year">${a.month.slice(0,4)} SEASON</span><span class="badge">5일차 완료</span></div><div class="archive-month">${Number(a.month.slice(5))}월 클랜전</div><div class="archive-stats"><div>클랜 순위<strong class="numeric">${a.rank}<small>위</small></strong></div><div>총 피해량<strong class="numeric">${eok(a.damage)}<small>억</small></strong></div></div><button class="button full" data-action="archive-detail" data-id="${a.month}">기록 열기 ${icon('arrow')}</button></article>`).join('')}</div>`;}
function hallPage(){const rows=allStats().sort((a,b)=>b.contribution-a.contribution),top=[rows[1],rows[0],rows[2]];return `<div class="section-head"><h2>이달의 기록 보유자</h2><span class="section-meta">예시 기록 · ${ui.day}일차 기준</span></div><div class="podium-grid">${top.map((m,i)=>`<article class="panel podium-card ${i===1?'top':''}"><div class="trophy">${icon(i===1?'trophy':'spark')}</div>${avatar(m.member)}<h3>${X(m.member.name)}</h3><p>${i===1?'누적 기여도 1위':i===0?'누적 기여도 2위':'누적 기여도 3위'}</p><div class="numeric">${eok(m.contribution)}억</div><button class="text-button" style="margin-top:14px;color:inherit" data-action="profile" data-id="${m.member.id}">개인 이력 ${icon('arrow')}</button></article>`).join('')}</div><section class="panel"><div class="panel-head"><h2>보스별 최고 피해량</h2></div><div class="table-wrap"><table><thead><tr><th>보스</th><th>클랜원</th><th class="right">최고 피해량</th><th class="right">기록 일차</th></tr></thead><tbody>${data.bosses.map(b=>{const l=data.logs.filter(l=>l.boss===b.id&&l.day<=ui.day).sort((a,b)=>b.actual-a.actual)[0];return `<tr><td><span class="boss-dot" style="${bossStyle(b.id)}"><i></i>${b.id}넴</span></td><td>${l?X(currentMember(l.memberId).name):'—'}</td><td class="right numeric">${l?nf(l.actual):'—'}</td><td class="right">${l?l.day+'일차':'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function clanPage(){return pageHeading('우리의 클랜','CLAN & KNOWLEDGE','함께하는 사람과 운영 기준을 한곳에.',ui.tabs.clan==='members'?'add-member':'')+pageTabs([['members','클랜원',data.members.filter(m=>m.status==='active').length],['rates','기여도 기준'],['guide','운영 가이드']])+({members:rosterPage,rates:ratesPage,guide:guidePage}[ui.tabs.clan]||rosterPage)();}
function rosterPage(){const members=data.members.filter(m=>ui.memberFilter==='all'||m.status===ui.memberFilter);return `<div class="toolbar"><div class="toolbar-left"><div class="filter-group" aria-label="클랜원 재적 상태">${[['active','현재 클랜원'],['graduated','졸업 클랜원'],['all','전체 이력']].map(([k,v])=>`<button data-action="member-filter" data-value="${k}" class="${ui.memberFilter===k?'active':''}">${v}</button>`).join('')}</div></div><span class="section-meta">${members.length}명</span></div><div class="roster-grid">${members.length?members.map(m=>`<button class="panel roster-card" data-action="edit-member" data-id="${m.id}">${avatar(m)}<div><h3>${X(m.name)}</h3><p>${X(m.uid)}<br>${m.joined.slice(0,7).replace('-','.')} 합류</p></div><span class="badge ${m.status==='active'?'green':''}">${m.status==='active'?'활동':'졸업'}</span></button>`).join(''):empty('해당하는 클랜원이 없습니다.','상태를 변경해 확인할 수 있습니다.')}</div>`;}
function ratesPage(){return `<div class="info-line">${icon('info')}<span>화면 체험을 위한 예시 배율입니다. 저장하면 시제품의 기여도와 순위에 반영됩니다.</span></div><section class="panel"><div class="panel-head"><div><h2>단계별 보스 배율</h2><p>실제 게임의 배율과 다를 수 있습니다.</p></div></div><form data-form="rates"><div class="table-wrap"><table class="rate-table"><thead><tr><th>단계</th>${data.bosses.map(b=>`<th class="center"><span style="color:var(--b${b.id})">${b.id}넴</span></th>`).join('')}</tr></thead><tbody>${data.rates.map((row,i)=>`<tr><td><strong>${i+2}단계</strong></td>${row.map((v,j)=>`<td class="center"><input type="number" min="0.1" max="99" step="0.1" value="${v}" name="rate-${i}-${j}" aria-label="${i+2}단계 ${j+1}넴 배율" required></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-body" style="padding-top:18px;display:flex;justify-content:flex-end"><button class="button primary" type="submit">${icon('check')}배율 저장</button></div></form></section>`;}
function guidePage(){return `<div class="tool-grid"><section class="panel"><div class="panel-head"><h2>운영 기준</h2>${icon('shield')}</div><div class="panel-body"><div class="result-line"><span>기본 참가 인원</span><strong>30명</strong></div><div class="result-line"><span>진행 일수</span><strong>${data.settings.days}일</strong></div><div class="result-line"><span>하루 기본 공격</span><strong>${data.settings.daily}타</strong></div><div class="result-line"><span>이월 사용</span><strong>기본 타수와 별도</strong></div><button class="button full" data-action="settings-rules" style="margin-top:20px">운영 설정 열기 ${icon('arrow')}</button></div></section><section class="panel"><div class="panel-head"><h2>택틱 표기 기준</h2>${icon('file')}</div><div class="panel-body"><div class="toggle-line"><div><strong>원문과 행동 순서 보존</strong><small>외부 택틱 도구는 시간만 바꾸고 원문을 유지합니다.</small></div></div><div class="toggle-line"><div><strong>주의가 필요한 육성 조건</strong><small>손컨이 0회보다 많거나 TP에 +가 있으면 빨간색으로 표시합니다.</small></div></div><div class="toggle-line"><div><strong>성급은 필요한 자리만 강조</strong><small>5성·6성이 아닌 숫자만 빨간색으로 표시합니다.</small></div></div><div class="toggle-line"><div><strong>숨긴 택틱은 작업실에 보관</strong><small>추천 조합에서 제외해도 택틱 본문은 유지됩니다.</small></div></div></div></section></div>`;}
function openDrawer(title,body,footer='',subtitle='',wide=false,form=''){
 drawer.classList.toggle('wide',wide);drawer.innerHTML=`<div class="drawer-head"><div><h2 id="drawer-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="button icon-only quiet" data-action="close-drawer" aria-label="닫기">${icon('close')}</button></div>${form?`<form class="drawer-form" data-form="${form}">`:''}<div class="drawer-body">${body}</div>${footer?`<div class="drawer-footer">${footer}</div>`:''}${form?'</form>':''}`;if(typeof dockInlineDrawer==='function')dockInlineDrawer();else if(!drawer.open)drawer.showModal();
}
function closeDrawer(){drawer.close();if(typeof detachInlineDrawer==='function')detachInlineDrawer();ui.imageUrl=null;}
function ensureEdit(){if(data.settings.editable)return true;toast('열람 모드입니다. 환경설정에서 체험 편집을 켜세요.');return false;}
function openLog(id=null,bossId=null){if(!ensureEdit())return;const log=data.logs.find(l=>l.id===id);let b=log?bossBy(log.boss):bossBy(bossId||ui.boss||1);if(!log&&isLocked(b)){toast('회차가 앞서 대기 중인 보스입니다. 다른 보스를 선택하세요.');return;}const member=log?currentMember(log.memberId):(allStats().find(m=>m.remaining>0)?.member||data.members[0]);
 openDrawer(log?'공격 기록 수정':'공격 기록',`${ui.imageUrl?`<img class="image-preview" src="${ui.imageUrl}" alt="사용자가 선택한 참고 이미지">`:''}<input type="hidden" name="logId" value="${X(log?.id||'')}"><div class="field-row"><div class="field"><label for="log-member">클랜원</label><select id="log-member" name="memberId" data-input="log-preview">${data.members.filter(m=>m.status==='active'||m.id===log?.memberId).map(m=>`<option value="${m.id}" ${m.id===member.id?'selected':''}>${X(m.name)}</option>`).join('')}</select></div><div class="field"><label for="log-day">일차</label><select id="log-day" name="day" data-input="log-preview">${Array.from({length:data.settings.days},(_,i)=>`<option value="${i+1}" ${(log?.day||ui.day)===i+1?'selected':''}>${i+1}일차</option>`).join('')}</select></div></div><div class="field"><label for="log-boss">공격한 보스</label><select id="log-boss" name="boss" data-input="log-preview">${data.bosses.map(v=>`<option value="${v.id}" ${v.id===b.id?'selected':''} ${!log&&isLocked(v)?'disabled':''}>${v.id}넴 · ${X(v.name)}${!log&&isLocked(v)?' · 회차 대기':''}</option>`).join('')}</select></div><div class="drawer-boss-preview" id="log-boss-preview"></div><div class="field-row"><div class="field"><label for="log-damage">기록 피해량</label><input id="log-damage" name="damage" type="number" min="0.00000001" step="any" required placeholder="예: 3.15" value="${log?log.damage/1e8:''}" data-input="log-preview" autofocus></div><div class="field"><label for="log-unit">입력 단위</label><select id="log-unit" name="unit" data-input="log-preview"><option value="100000000">억</option><option value="10000">만</option><option value="1">전체 숫자</option></select></div></div><label class="check-label"><input id="log-is-carry" type="checkbox" name="usesCarry" ${log?.type==='carry'||log?.usesCarry?'checked':''} data-input="log-preview">보유한 이월로 공격</label><div class="field-row"><div class="field"><label for="log-remaining">격파 순간 남은 시간</label><input id="log-remaining" name="remaining" placeholder="선택 · 예: 0:35" value="${log?.carrySeconds?fmtTime(Math.max(0,log.carrySeconds-20)):''}" inputmode="numeric" data-input="log-preview"><small>입력하면 이월 시간을 미리 계산합니다.</small></div><div class="field"><label for="log-note">메모</label><input id="log-note" name="note" placeholder="선택 입력" value="${X(log?.note||'')}"></div></div><div id="log-preview"></div><p class="helper" id="log-limit-note"></p>`,`${log?`<button type="button" class="button quiet danger" data-action="delete-log" data-id="${log.id}">${icon('trash')}삭제</button>`:'<button type="button" class="button" data-action="close-drawer">취소</button>'}<button type="submit" class="button primary">${icon('check')}${log?'수정 저장':'기록 등록'}</button>`,'예시 기록 · 이 브라우저에만 저장',false,'log');updateLogPreview();
}
function updateLogPreview(){const form=drawer.querySelector('form[data-form="log"]');if(!form)return;const fd=new FormData(form),b=bossBy(fd.get('boss')),damage=Math.max(0,Number(fd.get('damage'))*Number(fd.get('unit'))),hp=data.logs.find(l=>l.id===fd.get('logId'))?.actual||b.hp,actual=Math.min(hp,damage),kill=damage>=hp&&damage>0,remaining=timeToSec(fd.get('remaining')),carry=kill?Math.min(90,(Number.isFinite(remaining)?remaining:0)+20):0;document.getElementById('log-boss-preview').innerHTML=`<span class="boss-emblem" style="${bossStyle(b.id)}">${icon(b.icon)}</span><div><strong>${X(b.name)}</strong><small>${b.stage}단계 · ${b.lap}회차 · 남은 HP ${nf(b.hp)}</small></div>`;document.getElementById('log-preview').innerHTML=`<div class="result-line"><span>기록 피해량</span><strong class="numeric">${nf(damage)}</strong></div><div class="result-line"><span>초과 피해</span><strong class="numeric">${nf(Math.max(0,damage-hp))}</strong></div>${kill?`<div class="result-line"><span>격파 후 이월 ${!Number.isFinite(remaining)?'· 남은 시간 입력 필요':''}</span><strong class="mono">${Number.isFinite(remaining)?fmtTime(carry):'—'}</strong></div>`:''}<div class="result-line total"><span>반영될 실제 피해량</span><strong class="numeric">${nf(actual)}</strong></div>`;const m=currentMember(fd.get('memberId')),s=memberStats(m);document.getElementById('log-limit-note').textContent=`${m.name} · 현재 조회 일차 기준 기본 ${s.remaining}타 / 이월 ${s.carry}타 보유`;}
function rebuildBosses(){if(!data.baseBosses)data.baseBosses=structuredClone(data.bosses);data.bosses=structuredClone(data.baseBosses);for(const l of data.logs.filter(l=>l.newInDemo).sort((a,b)=>a.seq-b.seq)){const b=bossBy(l.boss);l.lap=b.lap;l.stage=b.stage;l.actual=Math.min(l.damage,b.hp);if(l.damage>=b.hp){l.type='kill';b.lap++;b.hp=b.max;}else{l.type=l.usesCarry?'carry':'normal';b.hp-=l.actual;}}}
function saveLog(form){const fd=new FormData(form),id=fd.get('logId'),old=data.logs.find(l=>l.id===id),boss=Number(fd.get('boss')),memberId=String(fd.get('memberId')),day=Number(fd.get('day')),damage=Math.round(Number(fd.get('damage'))*Number(fd.get('unit'))),usesCarry=fd.has('usesCarry');if(!Number.isFinite(damage)||damage<=0){toast('피해량을 0보다 크게 입력하세요.');return;}if(!old&&isLocked(bossBy(boss))){toast('회차 대기 중인 보스에는 공격을 등록할 수 없습니다.');return;}
 const relevant=data.logs.filter(l=>l.day===day&&l.memberId===memberId&&l.id!==id),used=relevant.filter(l=>l.type!=='carry'&&!l.usesCarry).length,availableCarry=relevant.filter(l=>l.type==='kill').length-relevant.filter(l=>l.type==='carry'||l.usesCarry).length;
 if(!old&&!usesCarry&&used>=data.settings.daily){toast('이 클랜원은 선택한 일차의 기본 공격을 모두 사용했습니다.');return;}if(!old&&usesCarry&&availableCarry<=0){toast('선택한 일차에 보유한 이월이 없습니다.');return;}
 const sec=fd.get('remaining')?timeToSec(fd.get('remaining')):NaN;if(fd.get('remaining')&&(!Number.isFinite(sec)||sec<0||sec>90)){toast('남은 시간은 0:00부터 1:30 사이로 입력하세요.');return;}
 checkpoint();if(!data.baseBosses)data.baseBosses=structuredClone(data.bosses);if(old){Object.assign(old,{memberId,day,boss,damage,actual:Math.min(damage,old.type==='kill'?old.actual:damage),usesCarry,note:String(fd.get('note')),carrySeconds:Number.isFinite(sec)?Math.min(90,sec+20):old.carrySeconds});if(!old.newInDemo)old.type=usesCarry?'carry':old.type==='kill'?'kill':'normal';}else{const b=bossBy(boss),now=new Date();data.logs.push({id:uid(),seq:Math.max(0,...data.logs.map(l=>l.seq))+1,memberId,boss,day,lap:b.lap,stage:b.stage,damage,actual:Math.min(damage,b.hp),type:damage>=b.hp?'kill':usesCarry?'carry':'normal',usesCarry,newInDemo:true,carrySeconds:Number.isFinite(sec)?Math.min(90,sec+20):0,note:String(fd.get('note')),time:`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,created:Date.now()});}rebuildBosses();persist();closeDrawer();render();toast(old?'공격 기록을 수정했습니다.':'공격 기록을 등록했습니다.',true);}
function openTacticDetail(id){const t=data.tactics.find(t=>t.id===id);if(!t)return;openDrawer(`${t.boss}넴 · ${X(t.title)}`,`<div class="editor-meta"><span class="badge">${t.stage}단계</span><span class="badge">기대딜 ${t.damage.toFixed(1)}억</span>${t.hidden?'<span class="badge amber">숨김</span>':''}</div>${party(t)}<div class="tactic-metadata">${tacticMeta(t)}</div><div class="editor-controls"><span class="carry-inline"><label for="detail-carry">이월 받은 시간</label><input id="detail-carry" value="${fmtTime(ui.carry)}" data-input="detail-carry" data-id="${t.id}" inputmode="numeric"></span><button class="text-button" data-action="copy-tactic" data-id="${t.id}">${icon('copy')}택틱 복사</button></div><div id="detail-timeline">${timeline(t)}</div><p class="helper">${X(t.note)}</p>`,`<button class="button" data-action="close-drawer">닫기</button><button class="button primary" data-action="open-in-workspace" data-id="${t.id}">작업실에서 열기 ${icon('arrow')}</button>`,X(bossBy(t.boss).name),true);}
function openTacticForm(id=null){if(!ensureEdit())return;const t=data.tactics.find(t=>t.id===id)||{id:'',boss:ui.boss||1,title:'새로운 택틱',damage:3,hands:0,tp:'4.2',party:CHARACTERS.slice(0,5),stars:[5,5,5,5,5],support:-1,category:'main',text:'1:30 AUTO 먼저 ON\n1:00 전원 SET',note:''};openDrawer(t.id?'택틱 수정':'새 택틱 등록',`<input type="hidden" name="tacticId" value="${t.id}"><div class="field"><label for="tactic-title">택틱 이름</label><input name="title" id="tactic-title" value="${X(t.title)}" required maxlength="70"></div><div class="field-row"><div class="field"><label for="tactic-boss">보스</label><select name="boss" id="tactic-boss">${data.bosses.map(b=>`<option value="${b.id}" ${b.id===t.boss?'selected':''}>${b.id}넴 · ${X(b.name)}</option>`).join('')}</select></div><div class="field"><label for="tactic-category">분류</label><select id="tactic-category" name="category"><option value="main" ${t.category==='main'?'selected':''}>택틱정리</option><option value="tabi" ${t.category==='tabi'?'selected':''}>타비비토</option></select></div></div><div class="field-row"><div class="field"><label for="tactic-damage">기대딜 · 억</label><input type="number" id="tactic-damage" name="damage" min="0.1" step="0.1" value="${t.damage}" required></div><div class="field"><label for="tactic-hands">손컨 횟수</label><input type="number" id="tactic-hands" name="hands" min="0" step="0.5" value="${t.hands}" required></div></div><div class="field-row"><div class="field"><label for="tactic-tp">TP 레벨</label><input id="tactic-tp" name="tp" value="${X(t.tp)}" placeholder="예: 4.2+"></div><div class="field"><label for="tactic-support">빌릴 캐릭터</label><select id="tactic-support" name="support">${[0,1,2,3,4].map(i=>`<option value="${i}" ${i===t.support?'selected':''}>${i+1}번째 캐릭터</option>`).join('')}</select></div></div><div class="drawer-section-title">편성 · 순서 유지</div>${Array.from({length:5},(_,i)=>`<div class="field-row" style="grid-template-columns:1fr 90px;margin-top:12px"><div class="field" style="margin:0"><label for="party-${i}">${i+1}번째 캐릭터</label><select id="party-${i}" name="party-${i}">${[...new Set([...CHARACTERS,t.party[i]])].map(c=>`<option ${c===t.party[i]?'selected':''}>${X(c)}</option>`).join('')}</select></div><div class="field" style="margin:0"><label for="star-${i}">성급</label><select name="star-${i}" id="star-${i}">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${Number(t.stars[i])===n?'selected':''}>★ ${n}</option>`).join('')}</select></div></div>`).join('')}<div class="field" style="margin-top:22px"><label for="tactic-text">택틱 본문</label><textarea name="text" id="tactic-text" rows="8" required>${X(t.text)}</textarea><small>한 줄에 남은 시간과 행동을 입력하세요. 예: 1:12 유이 후 레이 ON</small></div><div class="field"><label for="tactic-note">육성 조건 · 비고</label><textarea name="note" id="tactic-note" style="min-height:85px">${X(t.note)}</textarea></div>`,`<button type="button" class="button" data-action="close-drawer">취소</button><button class="button primary" type="submit">${icon('check')}택틱 저장</button>`,'저장한 택틱은 추천 조합에도 반영됩니다.',true,'tactic');}
function saveTactic(form){const fd=new FormData(form),old=data.tactics.find(t=>t.id===fd.get('tacticId'));checkpoint();const values={title:String(fd.get('title')).trim(),boss:Number(fd.get('boss')),stage:4,damage:Number(fd.get('damage')),hands:Number(fd.get('hands')),tp:String(fd.get('tp')),party:Array.from({length:5},(_,i)=>String(fd.get('party-'+i))),stars:Array.from({length:5},(_,i)=>Number(fd.get('star-'+i))),support:Number(fd.get('support')),category:String(fd.get('category')),text:String(fd.get('text')),note:String(fd.get('note'))};if(old)Object.assign(old,values);else{const t={id:uid(),...values,hidden:false};data.tactics.push(t);ui.selectedTactic=t.id;}persist();closeDrawer();ui.library=values.category;ui.boss=0;nav('tactics','workspace');toast('택틱을 저장하고 추천 조합에 반영했습니다.',true);}
function openMemberForm(id=null){if(!ensureEdit())return;const m=data.members.find(m=>m.id===id)||{id:'',name:'',uid:'',status:'active',joined:'2026-10-01',note:''};openDrawer(m.id?'클랜원 정보':'클랜원 추가',`<input type="hidden" name="memberId" value="${m.id}"><div class="field"><label for="member-name">닉네임</label><input id="member-name" name="name" value="${X(m.name)}" maxlength="20" required></div><div class="field"><label for="member-uid">UID</label><input id="member-uid" name="uid" value="${X(m.uid)}" placeholder="선택 입력"></div><div class="field-row"><div class="field"><label for="member-status">현재 상태</label><select name="status" id="member-status"><option value="active" ${m.status==='active'?'selected':''}>활동</option><option value="graduated" ${m.status==='graduated'?'selected':''}>졸업</option></select></div><div class="field"><label for="member-joined">합류일</label><input id="member-joined" name="joined" type="date" value="${m.joined}" required></div></div><div class="field"><label for="member-note">메모</label><textarea id="member-note" name="note" style="min-height:120px">${X(m.note)}</textarea></div><div class="drawer-note">졸업으로 바꿔도 공격 기록과 개인 이력은 보관됩니다.</div>`,`<button type="button" class="button" data-action="close-drawer">취소</button><button class="button primary" type="submit">${icon('check')}저장</button>`,'예시 클랜원 관리',false,'member');}
function saveMember(form){const fd=new FormData(form),name=String(fd.get('name')).trim();if(!name){toast('닉네임을 입력하세요.');return;}if(data.members.some(m=>m.name===name&&m.id!==fd.get('memberId'))){toast('같은 닉네임의 클랜원이 있습니다.');return;}checkpoint();const old=data.members.find(m=>m.id===fd.get('memberId')),values={name,uid:String(fd.get('uid')),status:String(fd.get('status')),joined:String(fd.get('joined')),note:String(fd.get('note'))};if(old)Object.assign(old,values);else data.members.push({id:uid(),...values});persist();closeDrawer();render();toast('클랜원 정보를 저장했습니다.',true);}
function settingsBody(){const s=data.settings;if(ui.settingsTab==='display')return `<div class="drawer-section-title" style="margin-top:0">화면 테마</div><div class="theme-options">${[['light','sun','라이트'],['dark','moon','다크']].map(([v,i,t])=>`<button class="theme-option ${s.theme===v?'active':''}" data-action="set-theme" data-value="${v}" aria-pressed="${s.theme===v}">${icon(i)}${t}</button>`).join('')}</div><label class="toggle-line"><span><strong>본문 크게 보기</strong><small>표와 택틱의 주요 글자를 더 크게 표시합니다.</small></span><span class="switch"><input type="checkbox" data-setting="large" ${s.large?'checked':''}><span></span></span></label><label class="toggle-line"><span><strong>촘촘한 간격</strong><small>글자 크기를 유지하며 행과 카드 여백을 줄입니다.</small></span><span class="switch"><input type="checkbox" data-setting="compact" ${s.compact?'checked':''}><span></span></span></label><label class="toggle-line"><span><strong>체험 편집</strong><small>끄면 기록·택틱·클랜원 수정을 잠급니다.</small></span><span class="switch"><input type="checkbox" data-setting="editable" ${s.editable?'checked':''}><span></span></span></label><p class="helper">표시 설정과 체험 편집은 이 브라우저에만 적용됩니다.</p>`;
 if(ui.settingsTab==='rules')return `<form data-form="rules"><div class="field"><label for="rule-days">클랜전 진행 일수</label><select id="rule-days" name="days">${[3,4,5,6,7].map(n=>`<option value="${n}" ${n===s.days?'selected':''}>${n}일</option>`).join('')}</select></div><div class="field"><label for="rule-daily">하루 기본 공격</label><input id="rule-daily" name="daily" type="number" min="1" max="5" value="${s.daily}" required></div><div class="field"><label for="rule-day">기본 조회 일차</label><select id="rule-day" name="defaultDay">${Array.from({length:s.days},(_,i)=>`<option value="${i+1}" ${s.defaultDay===i+1?'selected':''}>${i+1}일차</option>`).join('')}</select></div><div class="drawer-note">회차가 가장 느린 보스보다 2회차 앞선 보스는 시제품에서 공격 대기 상태로 표시합니다.</div><button class="button primary full" type="submit">운영 기준 저장</button></form>`;
 return `<div class="drawer-note">이 사이트는 독립된 디자인 시제품입니다. 모든 이름·보스·기록·택틱은 화면 체험용이며, 기존 사이트나 저장소에 연결되어 있지 않습니다.</div><div class="toggle-line"><div><strong>시제품 백업</strong><small>이 브라우저에서 바꾼 예시 데이터를 저장합니다.</small></div><button class="button sm" data-action="export-json">${icon('download')}백업</button></div><div class="field" style="margin-top:20px"><label for="restore-file">시제품 백업 복원</label><input type="file" id="restore-file" accept=".json,application/json" data-input="restore-json"><small>이 시제품에서 내보낸 백업만 사용할 수 있습니다.</small></div><div class="toggle-line"><div><strong>예시 데이터 초기화</strong><small>이 시제품에서 바꾼 내용만 초기 상태로 되돌립니다.</small></div><button class="button sm quiet danger" data-action="reset-confirm">초기화</button></div>`;}
function openSettings(tab=null){if(tab)ui.settingsTab=tab;openDrawer('환경설정',settingsBody(),'<button class="button primary" data-action="close-drawer">완료</button>','나에게 맞는 화면과 운영 기준');drawer.querySelector('.drawer-head').insertAdjacentHTML('afterend',`<div class="settings-tabs" role="tablist" aria-label="환경설정 항목">${[['display','화면'],['rules','운영 기준'],['data','시제품 데이터']].map(([v,t])=>`<button role="tab" aria-selected="${ui.settingsTab===v}" class="${ui.settingsTab===v?'active':''}" data-action="settings-tab" data-value="${v}">${t}</button>`).join('')}</div>`);}
function openArchive(month){const a=ARCHIVES.find(a=>a.month===month)||ARCHIVES[0];openDrawer(`${a.month.replace('-','년 ')}월 클랜전`,`<div class="drawer-note">현재 전황과 분리된 과거 기록 화면의 예시입니다.</div><div class="stat-strip" style="grid-template-columns:1fr 1fr">${stat('클랜 순위',`${a.rank}<small>위</small>`,'예시 순위')}${stat('총 피해량',`${eok(a.damage)}<small>억</small>`,'5일간 합계')}${stat('최고 진행',`${a.lap}<small>회차</small>`,'4단계 기준')}${stat('공격 기록',`${a.attacks}<small>타</small>`,'기본 + 이월')}</div><h3>시즌 메모</h3><p class="helper">함께 쌓아온 기록을 월별로 보관하는 공간입니다. 실제 아카이브를 연결하기 전의 예시이며, 현재 클랜전의 입력과 분리되어 있습니다.</p>`,`<button class="button" data-action="close-drawer">닫기</button><button class="button primary" data-action="archive-print">${icon('print')}기록 인쇄</button>`,'PAST SEASON · 예시 아카이브');}
function imageImport(){if(!ensureEdit())return;openDrawer('이미지를 보며 기록',`<div class="drawer-note">이미지를 참고하면서 옆에서 기록을 입력하는 체험 기능입니다. 이 시제품에는 자동 문자 인식이 연결되어 있지 않습니다.</div><div class="upload-area"><p>${icon('image')}</p><p>참고할 스크린샷을 선택하세요.</p><input id="battle-image" type="file" accept="image/*" data-input="battle-image" aria-label="참고 스크린샷 선택"></div><div id="image-preview-area"></div>`,`<button class="button" data-action="close-drawer">닫기</button><button class="button primary" data-action="image-to-log">공격 기록 열기 ${icon('arrow')}</button>`);}
function downloadFile(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function exportCSV(){const rows=[['일차','회차','보스','클랜원','기록 피해량','실제 피해량','유형'],...data.logs.filter(l=>l.day===ui.day).map(l=>[l.day,l.lap,l.boss+'넴',currentMember(l.memberId).name,l.damage,l.actual,logTypeLabel(l.type)])];downloadFile('\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),`Re2Dive_예시배틀로그_${ui.day}일차.csv`,'text/csv;charset=utf-8');toast('조회 일차의 예시 배틀로그를 내보냈습니다.');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('복사했습니다.');}catch{const el=document.createElement('textarea');el.value=text;el.style.position='fixed';el.style.opacity='0';(drawer.open?drawer:document.body).append(el);el.select();const ok=document.execCommand('copy');el.remove();toast(ok?'복사했습니다.':'복사할 텍스트를 직접 선택해주세요.');}}
function confirmReset(){openDrawer('예시 데이터를 초기화할까요?',`<div class="drawer-note">이 시제품에서 추가·수정한 기록과 택틱이 처음 예시 상태로 돌아갑니다. 초기화 후 되돌리기를 사용할 수 있습니다.</div>`,`<button class="button" data-action="settings" data-value="data">취소</button><button class="button primary" data-action="reset-demo">예시 데이터 초기화</button>`);}
function removeLog(id){if(!ensureEdit())return;checkpoint();data.logs=data.logs.filter(l=>l.id!==id);rebuildBosses();persist();closeDrawer();render();toast('공격 기록을 삭제했습니다.',true);}
function printPage(){if(!adminMode())return;if(drawer.open){drawer.classList.add('print-dialog');}window.print();drawer.classList.remove('print-dialog');}

document.addEventListener('click',event=>{if(typeof handleCopyPick==='function'&&handleCopyPick(event))return;ui.drawerTrigger=event.target.closest('[data-action]');},true);
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;
 if(a==='nav'){nav(v);return;}if(a==='tab'){ui.tabs[el.dataset.group]=v;ui.query='';ui.page=1;ui.boss=0;history.replaceState(null,'','#'+ui.section+'/'+v+(ui.section==='records'&&v==='history'&&ext.honorsView==='counts'?'/counts':''));render();return;}if(a==='day'){ui.day=Number(v);ui.page=1;render();return;}if(a==='settings'){openSettings(v||null);return;}if(a==='settings-rules'){openSettings('rules');return;}if(a==='settings-tab'){openSettings(v);return;}if(a==='close-drawer'){closeDrawer();return;}
 if(a==='theme'||a==='set-theme'){data.settings.theme=a==='theme'?(data.settings.theme==='light'?'dark':'light'):v;persist();render();if(drawer.open)openSettings();return;}
 if(a==='add-log'){openLog();return;}if(a==='boss-log'){openLog(null,Number(id));return;}if(a==='edit-log'){openLog(id);return;}if(a==='delete-log'){removeLog(id);return;}
 if(a==='undo'){if(!undoState)return;data=undoState;undoState=null;persist();render();if(drawer.open)closeDrawer();toast('직전 변경을 되돌렸습니다.');return;}
 if(a==='overview-members'){nav('overview','members');return;}if(a==='member-sort'){if(ui.memberSort===v)ui.sortDir*=-1;else{ui.memberSort=v;ui.sortDir=v==='name'?1:-1;}render();return;}
 if(a==='profile'){ui.profile=id;nav('records','profile');return;}if(a==='member-log'){nav('battle');ui.query=currentMember(id).name;render();return;}
 if(a==='boss-filter'){ui.boss=Number(v);ui.page=1;render();return;}if(a==='log-page'){ui.page=Number(v);render();return;}if(a==='export-csv'){exportCSV();return;}
 if(a==='rank-sort'){ui.rankSort=v;render();return;}if(a==='print'||a==='archive-print'){printPage();return;}if(a==='archive-detail'){openArchive(id);return;}
 if(a==='tactic-detail'){openTacticDetail(id);return;}if(a==='open-in-workspace'){ui.selectedTactic=id;ui.library=data.tactics.find(t=>t.id===id)?.hidden?'hidden':'all';closeDrawer();nav('tactics','workspace');return;}
 if(a==='toggle-library'){ui.libraryOpen=!ui.libraryOpen;render();return;}if(a==='select-tactic'){ui.selectedTactic=id;ui.libraryOpen=true;render();return;}if(a==='library'){ui.library=v;render();return;}
 if(a==='new-tactic'){openTacticForm();return;}if(a==='edit-tactic'){openTacticForm(id);return;}
 if(a==='hide-tactic'){if(!ensureEdit())return;checkpoint();const t=data.tactics.find(t=>t.id===id);t.hidden=!t.hidden;ui.picks=ui.picks.filter(i=>i!==id);persist();render();toast(t.hidden?'택틱을 숨겼습니다. 추천 조합에서 제외됩니다.':'택틱을 다시 공개했습니다.',true);return;}
 if(a==='duplicate-tactic'){if(!ensureEdit())return;checkpoint();const t=structuredClone(data.tactics.find(t=>t.id===id));t.id=uid();t.title+=' · 복사';data.tactics.push(t);ui.selectedTactic=t.id;persist();render();toast('택틱을 복제했습니다.',true);return;}
 if(a==='delete-tactic'){if(!ensureEdit())return;const t=data.tactics.find(t=>t.id===id);openDrawer('택틱을 삭제할까요?',`<div class="drawer-note">${X(t.title)}<br>추천 조합에서도 제외됩니다. 삭제 후 되돌리기를 사용할 수 있습니다.</div>`,`<button class="button" data-action="close-drawer">취소</button><button class="button primary" data-action="confirm-delete-tactic" data-id="${id}">삭제</button>`);return;}
 if(a==='confirm-delete-tactic'){checkpoint();data.tactics=data.tactics.filter(t=>t.id!==id);ui.picks=ui.picks.filter(t=>t!==id);persist();closeDrawer();render();toast('택틱을 삭제했습니다.',true);return;}
 if(a==='copy-tactic'){const t=data.tactics.find(t=>t.id===id);await copyText(adjustedText(t.text));return;}
 if(a==='reset-carry'){ui.carry=90;render();toast('원본 1:30 기준으로 되돌렸습니다.');return;}
 if(a==='pick-tactic'){if(ui.picks.includes(id))ui.picks=ui.picks.filter(i=>i!==id);else if(ui.picks.length<3)ui.picks.push(id);else{toast('3개 조합을 모두 골랐습니다. 하나를 해제하고 추가하세요.');return;}render();return;}
 if(a==='clear-plan'){ui.picks=[];render();return;}if(a==='auto-plan'){ui.picks=[1,2,3].map(b=>data.tactics.filter(t=>t.boss===b&&!t.hidden).sort((a,b)=>b.damage-a.damage)[0]?.id).filter(Boolean);render();toast('서로 다른 보스의 3타 예시를 골랐습니다.');return;}
 if(a==='apply-calculated-carry'){const n=timeToSec(document.getElementById('carry-result').textContent);if(!Number.isFinite(n)||n<=0){toast('시간 입력을 확인하세요.');return;}ui.carry=n;nav('tactics','workspace');toast(`${fmtTime(n)} 기준으로 택틱 시간을 맞췄습니다.`);return;}
 if(a==='copy-external'){await copyText(document.getElementById('external-output').textContent);return;}
 if(a==='add-member'){openMemberForm();return;}if(a==='edit-member'){openMemberForm(id);return;}if(a==='member-filter'){ui.memberFilter=v;render();return;}
 if(a==='export-json'){downloadFile(JSON.stringify(data,null,2),'Re2Dive_디자인시제품_백업.json','application/json');toast('시제품의 예시 데이터를 백업했습니다.');return;}if(a==='reset-confirm'){confirmReset();return;}
 if(a==='reset-demo'){checkpoint();data=seed();ui.day=3;ui.selectedTactic=data.tactics[0].id;ui.picks=[];ui.library='all';persist();closeDrawer();nav('overview','bosses');toast('처음 예시 상태로 돌아왔습니다.',true);return;}
 if(a==='image-import'){imageImport();return;}if(a==='image-to-log'){const image=ui.imageUrl;openLog();ui.imageUrl=image;return;}
});

document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(!ensureEdit())return;
 if(form.dataset.form==='log')saveLog(form);else if(form.dataset.form==='tactic')saveTactic(form);else if(form.dataset.form==='member')saveMember(form);
 else if(form.dataset.form==='rates'){const fd=new FormData(form);checkpoint();data.rates=data.rates.map((row,i)=>row.map((v,j)=>Number(fd.get(`rate-${i}-${j}`))));persist();render();toast('기여도 배율을 저장했습니다.',true);}
 else if(form.dataset.form==='rules'){const fd=new FormData(form);checkpoint();Object.assign(data.settings,{days:Number(fd.get('days')),daily:Number(fd.get('daily')),defaultDay:Math.min(Number(fd.get('defaultDay')),Number(fd.get('days')))});ui.day=Math.min(ui.day,data.settings.days);persist();render();openSettings('rules');toast('운영 기준을 저장했습니다.',true);}
});
let searchTimer;
document.addEventListener('input',event=>{const el=event.target,kind=el.dataset.input;
 if(kind==='log-preview')updateLogPreview();
 if(kind==='log-query'){ui.query=el.value;ui.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=el.selectionStart;render();const next=document.getElementById('log-query');next?.focus();next?.setSelectionRange(pos,pos);},130);}
 if(kind==='carry-calculator'||kind==='external-tactic')updateCarryTool();
 if(kind==='workspace-carry'||kind==='detail-carry'){const sec=timeToSec(el.value);if(Number.isFinite(sec)&&sec>0&&sec<=90){ui.carry=sec;const t=data.tactics.find(t=>t.id===(el.dataset.id||ui.selectedTactic));const target=document.getElementById(kind==='detail-carry'?'detail-timeline':'workspace-timeline');if(target&&t)target.innerHTML=timeline(t);}else el.setAttribute('aria-invalid','true');if(Number.isFinite(sec)&&sec>0&&sec<=90)el.removeAttribute('aria-invalid');}
});
document.addEventListener('change',async event=>{const el=event.target,kind=el.dataset.input;
 if(el.dataset.setting){data.settings[el.dataset.setting]=el.checked;persist();render();toast('화면 설정을 저장했습니다.');}
 if(kind==='month'){if(el.value!=='2026-10'){openArchive(el.value);el.value='2026-10';}return;}
 if(kind==='log-type'){ui.logType=el.value;ui.page=1;render();}if(kind==='profile-member'){ui.profile=el.value;render();}
 if(kind==='battle-image'&&el.files[0]){if(!el.files[0].type.startsWith('image/'))return;ui.imageUrl=URL.createObjectURL(el.files[0]);document.getElementById('image-preview-area').innerHTML=`<img class="image-preview" src="${ui.imageUrl}" alt="선택한 참고 스크린샷">`;}
 if(kind==='restore-json'&&el.files[0]){try{const incoming=JSON.parse(await el.files[0].text());if(incoming.version!==1||!Array.isArray(incoming.members)||!Array.isArray(incoming.logs)||!Array.isArray(incoming.tactics)||!Array.isArray(incoming.bosses)||!Array.isArray(incoming.rates)||!incoming.settings||!incoming.members.length||incoming.bosses.length!==5)throw new Error('format');checkpoint();data=incoming;ui.day=Math.min(data.settings.defaultDay,data.settings.days);ui.selectedTactic=data.tactics[0]?.id;ui.picks=[];persist();closeDrawer();nav('overview','bosses');toast('시제품 백업을 복원했습니다.',true);}catch{toast('이 시제품의 올바른 JSON 백업을 선택하세요.');}}
});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'&&drawer.open){const form=drawer.querySelector('form');if(form){event.preventDefault();form.requestSubmit();}}});
drawer.addEventListener('click',event=>{if(event.target===drawer){const r=drawer.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDrawer();}});
function skipToMain(event){
  if(!event.target.closest('a.skip-link'))return;
  const main=document.getElementById('main');if(!main)return;
  event.preventDefault();main.setAttribute('tabindex','-1');
  main.focus({preventScroll:true});main.scrollIntoView({block:'start'});
}
document.addEventListener('click',skipToMain);
window.addEventListener('popstate',()=>{parseHash();render();});window.addEventListener('hashchange',()=>{parseHash();render();});


